#!/usr/bin/env python3
"""gen_debug_mutants.py -- cut the debug planted defects (Track A plan 6A.5 G5) from the CURRENT
RTL and write tb/debug/run/debug_mut.toml. Rerun after any rtl/debug change. Each edit must match
exactly once, or the script stops (a defect that no longer applies is not silently dropped)."""
import os, re, sys
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", ".."))
M = [
 ("m01_w1c_clears_all","rtl/debug/debug_module.v","sberror <= sberror & ~wdata_i[14:12];","sberror <= 3'd0;","an sbcs W1C clears sberror whatever bits are written"),
 ("m02_no_busyerror","rtl/debug/debug_module.v","                    A_SBADDR0: begin\n                        if (sbbusy) sbbusyerror <= 1'b1;","                    A_SBADDR0: begin\n                        if (sbbusy) ;","an sbaddress0 write while busy does not set sbbusyerror"),
 ("m03_autoinc_8","rtl/debug/debug_module.v","if (sbautoinc)      sbaddr <= sbaddr + 32'd4;","if (sbautoinc)      sbaddr <= sbaddr + 32'd8;","auto-increment adds 8"),
 ("m04_no_readondata","rtl/debug/debug_module.v","else if (sbreadondata && sberror == 0 && !sbbusyerror) kick(1'b0);","else ;","sbreadondata ignored"),
 ("m05_dbg3_revert","rtl/debug/debug_module.v","                            sbreadondata <= 1'b0; sbaccess <= 3'd2; sberror <= 3'd0;\n                            sbaddr <= 32'd0; sbdata <= 32'd0;\n                        end else begin","                            sbreadondata <= 1'b0; sbaccess <= 3'd2; sberror <= 3'd0;\n                        end else begin","DBG-3 reverted: dmactive = 0 leaves sbaddress0/sbdata0"),
 ("m06_no_align_check","rtl/debug/debug_module.v","            else if (sbaddr[1:0] != 0)  sberror <= 3'd2;\n","","an unaligned sbaddress0 is not refused (kick)"),
 ("m07_no_access_check","rtl/debug/debug_module.v","            if (sbaccess != 3'd2)       sberror <= 3'd3;\n            else if","            if (1'b0)                   sberror <= 3'd3;\n            else if","an unsupported sbaccess is not refused (kick)"),
 ("m08_haltreq_ignored","rtl/debug/debug_module.v","if      (wdata_i[31]) halted_q <= 1'b1;","if      (1'b0) halted_q <= 1'b1;","haltreq ignored"),
 ("m09_unimpl_garbage","rtl/debug/debug_module.v","default:       rdata_o <= 32'd0;          // abstractcs, data0, progbuf ...","default:       rdata_o <= {25'd0, addr_i}; // MUTANT","an unimplemented address reads its address, not 0"),
 ("m10_ndmreset_bit2","rtl/debug/debug_module.v","ndmreset <= wdata_i[1];","ndmreset <= wdata_i[2];","ndmreset taken from bit 2"),
 ("m11_idcode_wrong","rtl/debug/dtm.v","localparam [31:0] IDCODE = 32'h0000_0DB1;","localparam [31:0] IDCODE = 32'h0000_0DB3;","IDCODE wrong"),
 ("m13_tlr_no_idcode","rtl/debug/jtag_tap.v","            if (st == TLR)   ir_q  <= IR_IDCODE;","            if (st == TLR)   ir_q  <= ir_q;","Test-Logic-Reset does not select IDCODE"),
 ("m14_sba_err_lost","rtl/debug/sba_master.v","                    err_o    <= hresp_i;","                    err_o    <= 1'b0;","an AHB ERROR on the SBA master is not reported"),
 ("m15_rdata_not_captured","rtl/debug/sba_master.v","                    if (!hwrite_o) rdata_o <= hrdata_i;","                    if (!hwrite_o) rdata_o <= rdata_o;   // MUTANT","SBA read data never captured"),
 ("m16_dbg7_revert","rtl/debug/debug_module.v","                            hartreset <= wdata_i[29];                  // the RW field\n                            if      (wdata_i[31]) halted_q <= 1'b1;","                            hartreset <= wdata_i[29];                  // the RW field\n                            if (!wdata_i[30] && !wdata_i[31]) halted_q <= 1'b0;   // MUTANT: DBG-7 back\n                            if      (wdata_i[31]) halted_q <= 1'b1;","DBG-7 reverted: a dmcontrol write without haltreq releases the halt"),
 ("m18_ack_not_cleared","rtl/debug/debug_module.v","halted_q <= 1'b0; resumeack_q <= 1'b0; resume_pend <= 1'b1;","halted_q <= 1'b0; resume_pend <= 1'b1;   // MUTANT: the old ack survives","resumereq does not clear allresumeack (a stale ack from the last resume)"),
 ("m17_no_resumeack","rtl/debug/debug_module.v","            if (resume_pend && !grant_q && !halt_requested) begin resumeack_q <= 1'b1; resume_pend <= 1'b0; end","            // MUTANT: DBG-8 back, the resume is never acknowledged","DBG-8 reverted: no allresumeack"),
]
# m12 (busy refusal at Update-DR does not set dmistat = 3) is EQUIVALENT: a_dtm_update_busy_sticky
# proves dmistat is already 3 there (fv_debug mut_m12_equiv); the mutant file is kept for that task.
EQUIV = [("m12_busy_not_sticky","rtl/debug/dtm.v","if (busy)                  dmistat <= 2'd3; // sticky busy","if (busy)                  ;               // MUTANT","a request refused as busy does not set dmistat = 3 (equivalent)")]
toml = ['''# Debug planted defects (plan 6A.5 G5, recipe R10). GENERATED by tb/debug/mut/gen_debug_mutants.py
# from the current RTL -- regenerate rather than edit. Each must FAIL through the benches' own
# [FAIL] checks (tb_debug with the random phase, or tb_debug_dm for DBG-7/DBG-8).
# Run: python3.12 tools/run/garuda_run.py suite tb/debug/run/debug_mut.toml
[suite]
block = "debug"
name  = "debug_mut"
kind  = "sim"
xfail = "tb/debug/run/xfail.tsv"

[defaults]
flist   = "tb/debug/filelist_debug.f"
top     = "tb_debug"
marker  = '^RESULT: PASSED'
timeout = 2400
plusargs = ["+RAND=300", "+SEED=7700"]
''']
xf = []
for n, f, a, b, d in M + EQUIV:
    src = open(os.path.join(ROOT, f)).read()
    if src.count(a) != 1: sys.exit(f"{n}: edit does not match exactly once in {f}")
    if a == b: sys.exit(f"{n}: the edit changes nothing")
    out = f"tb/debug/mut/{os.path.basename(f)[:-2]}_mut_{n}.v"
    open(os.path.join(ROOT, out), "w").write(f"// MUTANT {n}: {d}\n" + src.replace(a, b))
    if (n, f, a, b, d) in EQUIV: continue
    unit = n in ("m16_dbg7_revert", "m17_no_resumeack", "m18_ack_not_cleared")
    extra = '\nflist = "tb/debug/filelist_debug_dm.f"\ntop = "tb_debug_dm"\nplusargs = []' if unit else ""
    toml.append(f'\n# {d}\n[[test]]\nname = "mut_{n}"{extra}\nreplace = {{ "{f}" = "{out}" }}\nfail_reason = "^\\\\[FAIL\\\\] "\n')
    xf.append(f"debug_mut\tmut_{n}\tFAIL\tPLANTED\t{d}: the bench must report it\n")
open(os.path.join(ROOT, "tb/debug/run/debug_mut.toml"), "w").write("".join(toml))
x = os.path.join(ROOT, "tb/debug/run/xfail.tsv")
kept = [l for l in open(x) if not l.startswith("debug_mut\t")]
open(x, "w").write("".join(kept) + "".join(xf))
print(len(M), "mutants written,", len(EQUIV), "equivalent")
